/**
 * Sude idle + walk textures.
 * BW (Scene 1):  sude-{dir}.png + sude-{dir}-{1,2,3}.png
 * Color (Scene 2): sude-color-{dir}.png + sude-color-{dir}-{1,2,3}.png
 *
 * Generated by: python scripts/make_sude_walk_frames.py [bw|color|all]
 */

export const SUDE_DIRS = /** @type {const} */ (['down', 'up', 'left', 'right'])

/**
 * @param {'bw' | 'color'} variant
 */
export function getSudeVariant(variant) {
  const prefix = variant === 'color' ? 'sude-color' : 'sude'
  const idle = {}
  const walkFrameKey = (dir, n) => `${prefix}-${dir}-${n}`
  const walkFramePath = (dir, n) => `assets/characters/sude/${prefix}-${dir}-${n}.png`
  const animKeys = {}

  for (const dir of SUDE_DIRS) {
    idle[dir] = {
      key: `${prefix}-${dir}`,
      path: `assets/characters/sude/${prefix}-${dir}.png`,
    }
    animKeys[dir] = `${prefix}-walk-${dir}`
  }

  return {
    variant,
    prefix,
    idle,
    animKeys,
    frameRate: 10,
    walkFrameKey,
    walkFramePath,
  }
}

export const SUDE_BW = getSudeVariant('bw')
export const SUDE_COLOR = getSudeVariant('color')

/** @deprecated use SUDE_BW — kept for Scene1 import compatibility during refactor */
export const SUDE_IDLE = SUDE_BW.idle
export const SUDE_WALK = {
  frameRate: SUDE_BW.frameRate,
  animKeys: SUDE_BW.animKeys,
  frameKey: SUDE_BW.walkFrameKey,
  framePath: SUDE_BW.walkFramePath,
}

/**
 * @param {Phaser.Scene} scene
 * @param {ReturnType<typeof getSudeVariant>} pack
 */
export function preloadSudeVariant(scene, pack) {
  for (const dir of SUDE_DIRS) {
    scene.load.image(pack.idle[dir].key, pack.idle[dir].path)
    for (const n of /** @type {const} */ ([1, 2, 3])) {
      scene.load.image(pack.walkFrameKey(dir, n), pack.walkFramePath(dir, n))
    }
  }
}

/**
 * @param {Phaser.Scene} scene
 * @param {ReturnType<typeof getSudeVariant>} [pack]
 */
export function preloadSudeTextures(scene, pack = SUDE_BW) {
  preloadSudeVariant(scene, pack)
}

/**
 * @param {Phaser.Scene} scene
 * @param {ReturnType<typeof getSudeVariant>} pack
 */
export function ensureSudeWalkAnims(scene, pack = SUDE_BW) {
  for (const dir of SUDE_DIRS) {
    const key = pack.animKeys[dir]
    if (scene.anims.exists(key)) {
      scene.anims.remove(key)
    }
    scene.anims.create({
      key,
      frames: [
        { key: pack.walkFrameKey(dir, 1) },
        { key: pack.walkFrameKey(dir, 2) },
        { key: pack.walkFrameKey(dir, 3) },
        { key: pack.walkFrameKey(dir, 2) },
      ],
      frameRate: pack.frameRate,
      repeat: -1,
    })
  }
}

/**
 * Apply NEAREST filter to a Sude pack.
 * @param {Phaser.Scene} scene
 * @param {ReturnType<typeof getSudeVariant>} pack
 */
export function applySudeNearestFilter(scene, pack) {
  for (const dir of SUDE_DIRS) {
    const idleTex = scene.textures.get(pack.idle[dir].key)
    if (idleTex) idleTex.setFilter(Phaser.Textures.FilterMode.NEAREST)
    for (const n of /** @type {const} */ ([1, 2, 3])) {
      const tex = scene.textures.get(pack.walkFrameKey(dir, n))
      if (tex) tex.setFilter(Phaser.Textures.FilterMode.NEAREST)
    }
  }
}
